</section></main></div>
<?php if ($ready): ?><script>
(()=>{const api='api_temporary_pending_unpaid_archive.php',start=document.getElementById('startDate'),end=document.getElementById('endDate'),previewButton=document.getElementById('previewButton'),hideButton=document.getElementById('hideButton'),status=document.getElementById('status'),preview=document.getElementById('preview');let current=null,csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});let b;try{b=await r.json()}catch{throw new Error(`Unreadable server response (HTTP ${r.status}).`)}if(!r.ok||b.success!==true)throw new Error(b.error||`Request failed (HTTP ${r.status}).`);return b}
function clear(){current=null;hideButton.disabled=true;preview.hidden=true;preview.replaceChildren()}
async function loadPreview(){clear();if(!start.value||!end.value||start.value>end.value){status.className='pf-status error';status.textContent='Enter a valid date range.';return}previewButton.disabled=true;status.className='pf-status';status.textContent='Checking current order and payment records…';try{const q=new URLSearchParams({start_date:start.value,end_date:end.value});const b=await request(`${api}?${q}`);current=b;csrf=b.csrf_token||csrf;preview.innerHTML=`<table class="pf-table"><thead><tr><th>Order ID</th><th>Order date (Manila)</th><th>Customer</th><th>Branch</th><th>Total</th><th>Status</th><th>Payment</th></tr></thead><tbody>${(b.orders||[]).map(o=>`<tr><td>${Number(o.order_id)}</td><td>${esc(o.order_date)}</td><td>${esc(o.customer_name||'—')}</td><td>${esc(o.branch_id??'—')}</td><td>₱${Number(o.total_amount||0).toLocaleString('en-PH',{minimumFractionDigits:2})}</td><td>${esc(o.status)}</td><td>${esc(o.payment_status)}</td></tr>`).join('')||'<tr><td colspan="7">No eligible orders in this range.</td></tr>'}</tbody></table>`;preview.hidden=false;hideButton.disabled=b.count<1;status.className='pf-status success';status.textContent=`${b.count} eligible order(s). Exact order IDs: ${b.order_ids.length?b.order_ids.map(id=>'#'+id).join(', '):'none'}. Review the list above, then choose “Hide matching orders” to apply this preview.`}catch(e){status.className='pf-status error';status.textContent=`Preview failed: ${e.message}`}finally{previewButton.disabled=false}}
async function apply(){if(!current||current.count<1)return;hideButton.disabled=true;previewButton.disabled=true;status.className='pf-status';status.textContent='Rechecking the preview and applying archive visibility…';try{const b=await request(api,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({start_date:current.start_date,end_date:current.end_date,order_ids:current.order_ids,preview_token:current.preview_token,csrf_token:csrf})});status.className='pf-status success';status.textContent=`Archived ${b.count} order(s). Exact order IDs: ${b.order_ids.map(id=>'#'+id).join(', ')||'none'}. Reloading the preview to verify they are no longer eligible for operational lists…`;await loadPreview();if(current?.count===0){status.className='pf-status success';status.textContent=`Archived ${b.count} order(s). Exact order IDs: ${b.order_ids.map(id=>'#'+id).join(', ')||'none'}. The refreshed preview now contains 0 eligible orders.`}}catch(e){status.className='pf-status error';status.textContent=`Archive action failed: ${e.message}`;hideButton.disabled=false}finally{previewButton.disabled=false}}
previewButton.addEventListener('click',loadPreview);hideButton.addEventListener('click',apply);start.addEventListener('change',clear);end.addEventListener('change',clear);})();
</script><?php endif; ?></body></html>
